import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Weekly 001 — From Agent Frameworks to Governed Digital Employees","description":"","frontmatter":{"title":"Weekly 001 — From Agent Frameworks to Governed Digital Employees","outline":"deep"},"headers":[],"relativePath":"research/weekly/weekly-001.md","filePath":"research/weekly/weekly-001.md","lastUpdated":1785568227000}'),o={name:"research/weekly/weekly-001.md"};function s(l,e,r,c,p,d){return i(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="weekly-001-研究周报第-001-期" tabindex="-1">Weekly 001 / 研究周报第 001 期 <a class="header-anchor" href="#weekly-001-研究周报第-001-期" aria-label="Permalink to &quot;Weekly 001 / 研究周报第 001 期&quot;">​</a></h1><blockquote><p><strong>From Agent Frameworks to Governed Digital Employees</strong><br><strong>从 Agent 框架走向可治理的数字员工</strong><br> Observation window: 2026-07-24 — 2026-07-31</p></blockquote><h2 id="executive-synthesis-核心综合" tabindex="-1">Executive synthesis / 核心综合 <a class="header-anchor" href="#executive-synthesis-核心综合" aria-label="Permalink to &quot;Executive synthesis / 核心综合&quot;">​</a></h2><p>The first issue establishes the baseline of the Research Center:</p><ol><li>interoperability is becoming infrastructure, while governance remains the missing layer;</li><li>open-source systems are moving from chat agents toward runtime, orchestration and operator control;</li><li>enterprise vendors are packaging Digital Workforce products rather than generic Agent capability;</li><li>CodeFlowMu should not become another generic multi-agent framework;</li><li>the stable product direction is an SME-first Digital Employee Development and Runtime Platform.</li></ol><p>首期报告确认：互操作正在成为基础设施，治理成为缺失上层；开源工程正从聊天 Agent 转向 Runtime 与操作控制；企业购买的是岗位化数字劳动力，而不是抽象多 Agent 能力；CodeFlowMu 应收口为面向中小企业的数字员工开发与运行平台。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee</span></span>
<span class="line"><span>= Position</span></span>
<span class="line"><span>+ Responsibility</span></span>
<span class="line"><span>+ Skills</span></span>
<span class="line"><span>+ Workflow</span></span>
<span class="line"><span>+ Runtime</span></span>
<span class="line"><span>+ Governance</span></span>
<span class="line"><span>+ Evaluation</span></span></code></pre></div><h2 id="academic-signal-学术信号" tabindex="-1">Academic signal / 学术信号 <a class="header-anchor" href="#academic-signal-学术信号" aria-label="Permalink to &quot;Academic signal / 学术信号&quot;">​</a></h2><h3 id="governance-gaps-above-interoperability" tabindex="-1">Governance gaps above interoperability <a class="header-anchor" href="#governance-gaps-above-interoperability" aria-label="Permalink to &quot;Governance gaps above interoperability&quot;">​</a></h3><p>Recent protocol research compares MCP, A2A, ACP and related standards against governance dimensions such as membership, deliberation, dissent, human escalation, audit and replay. The important conclusion for TMPA is layered positioning:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Interoperability protocols</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>TMPA work-data and governance architecture</span></span></code></pre></div><p>TMPA should not compete as a universal communication protocol. It should govern assignment, evidence, verification, escalation, publication and recovery across different protocols.</p><h3 id="agent-societies-and-collective-governance" tabindex="-1">Agent societies and collective governance <a class="header-anchor" href="#agent-societies-and-collective-governance" aria-label="Permalink to &quot;Agent societies and collective governance&quot;">​</a></h3><p>Research is moving from single-Agent instruction following toward multi-Agent institutions, negotiation, information asymmetry and collective outcomes. This supports TMPA&#39;s focus on responsibility relations and system-level lifecycle control.</p><h2 id="github-engineering-baseline-github-工程基线" tabindex="-1">GitHub engineering baseline / GitHub 工程基线 <a class="header-anchor" href="#github-engineering-baseline-github-工程基线" aria-label="Permalink to &quot;GitHub engineering baseline / GitHub 工程基线&quot;">​</a></h2><h3 id="openhands-agent-canvas" tabindex="-1">OpenHands Agent Canvas <a class="header-anchor" href="#openhands-agent-canvas" aria-label="Permalink to &quot;OpenHands Agent Canvas&quot;">​</a></h3><p>The meaningful trend is not one UI feature. OpenHands is moving from a coding Agent toward an operator-facing workspace with skills, plugin visibility, connection health, desktop packaging and automation triggers.</p><p>CodeFlowMu should learn:</p><ul><li>connection health and startup visibility;</li><li>skill activation lifecycle;</li><li>operator-facing recovery and diagnostics.</li></ul><p>It should not copy generic workspace positioning. Its differentiation is persistent Position, responsibility, evidence and governance.</p><h3 id="autogen" tabindex="-1">AutoGen <a class="header-anchor" href="#autogen" aria-label="Permalink to &quot;AutoGen&quot;">​</a></h3><p>Nested teams, shared memory, MCP integration and resumable graph execution are becoming baseline technical primitives. They still do not define organizational ownership, completion evidence or publication authority. CodeFlowMu should remain provider-independent and keep its Position and governance layer stable.</p><h2 id="enterprise-digital-workforce-企业数字劳动力" tabindex="-1">Enterprise digital workforce / 企业数字劳动力 <a class="header-anchor" href="#enterprise-digital-workforce-企业数字劳动力" aria-label="Permalink to &quot;Enterprise digital workforce / 企业数字劳动力&quot;">​</a></h2><h3 id="servicenow" tabindex="-1">ServiceNow <a class="header-anchor" href="#servicenow" aria-label="Permalink to &quot;ServiceNow&quot;">​</a></h3><p>ServiceNow&#39;s Autonomous Workforce combines role-defined AI Specialists with deterministic enterprise workflows, escalation and centralized governance. The architectural lesson is that probabilistic intelligence needs deterministic workflow control and explicit authority.</p><h3 id="workday" tabindex="-1">Workday <a class="header-anchor" href="#workday" aria-label="Permalink to &quot;Workday&quot;">​</a></h3><p>Agent System of Record demonstrates the need for a persistent Registry that answers who owns an Agent, what role and skills it has, what it may access, what it costs, and whether it remains compliant.</p><h3 id="salesforce" tabindex="-1">Salesforce <a class="header-anchor" href="#salesforce" aria-label="Permalink to &quot;Salesforce&quot;">​</a></h3><p>Agentforce packages business outcomes by function. Users buy prospecting, service resolution or pipeline work—not “multi-agent capability.” CodeFlowMu should eventually provide executable position packages as well as a builder.</p><h2 id="impact-on-tmpa-对-tmpa-的影响" tabindex="-1">Impact on TMPA / 对 TMPA 的影响 <a class="header-anchor" href="#impact-on-tmpa-对-tmpa-的影响" aria-label="Permalink to &quot;Impact on TMPA / 对 TMPA 的影响&quot;">​</a></h2><ul><li>keep protocol independence;</li><li>define governance as executable lifecycle control;</li><li>retain SME-first positioning;</li><li>use Digital Employee as the primary application context;</li><li>evaluate evidence, escalation, recovery, human intervention and cost—not only task success.</li></ul><h2 id="impact-on-codeflowmu-对-codeflowmu-的影响" tabindex="-1">Impact on CodeFlowMu / 对 CodeFlowMu 的影响 <a class="header-anchor" href="#impact-on-codeflowmu-对-codeflowmu-的影响" aria-label="Permalink to &quot;Impact on CodeFlowMu / 对 CodeFlowMu 的影响&quot;">​</a></h2><p>Recommended positioning:</p><blockquote><p><strong>CodeFlowMu is an SME-first Digital Employee Development and Runtime Platform.</strong><br><strong>CodeFlowMu 是面向中小企业的数字员工开发与运行平台。</strong></p></blockquote><p>Initial priorities:</p><ol><li>Position definition;</li><li>Digital Employee Registry;</li><li>workflow and operation-node contracts;</li><li>runtime observability and recovery;</li><li>TMPA/FCoP evidence lifecycle;</li><li>cost and evaluation ledger.</li></ol>`,36)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
